{
  "object_operation_results": [
    {
      "object_id": "pipe66_t411",
      "operation": "identity_across_views",
      "status": "checked",
      "reason": "Осмотрены все 15 приложенных изображений, включая увеличения исходных блоков. На разрезе 6-6 и принципиальной схеме установлена одна и та же ветвь Т411: циркуляция ГВС жилья 1-й зоны, Ø45×2,5оц, T=55 °C, P=8,06 бар. Т412 отдельно обозначает циркуляцию аренды/ДОО; на схеме обе ветви объединяются в Т41 перед насосным узлом К15. Различие расходов Т411 сохранено отдельным замечанием. Повторные виды и увеличения не приняты за дополнительные физические ветви. Проверка идентичности ограничена установленными изображениями Т411.",
      "source_refs": [
        "blk_7527066e645e47bb917a9fc17fb82ccc",
        "blk_0103a941fa5a4b0d9141a4149e927bff",
        "blk_d4b7a506870a4c3dbe5a3d19eb26dfdc",
        "blk_6496640ac5e44e98a89acc7af56d0509",
        "blk_5d085f4c917a4e568fd33327e6f8edea",
        "blk_94b58ecf5d404f7d90c272d267eb2e48",
        "blk_06029d59a01b4b779037ffcee1ae5260",
        "blk_8e4e78d833774d1094ea7fc72932c0ff"
      ],
      "inspected_locations": [
        {
          "block_id": "blk_7527066e645e47bb917a9fc17fb82ccc",
          "description": "Разрез 6-6, верхняя левая подпись Т411 и соседняя подпись Т412; разрез 5-5 относится к греющему контуру К14."
        },
        {
          "block_id": "blk_0103a941fa5a4b0d9141a4149e927bff",
          "description": "Левая группа ГВС: отдельные ветви Т411 жилья и Т412 аренды/ДОО, их соединение в Т41 и дальнейший участок к К15. Остальные увеличения показывают другие системы и продолжение общей схемы."
        },
        {
          "block_id": "blk_d4b7a506870a4c3dbe5a3d19eb26dfdc",
          "description": "Разрез 4-4: узел К15 ГВС 1-й зоны; обозначения общих участков Т4 не приняты за индивидуальную маркировку Т411."
        },
        {
          "block_id": "blk_6496640ac5e44e98a89acc7af56d0509",
          "description": "Разрез 15-15: Т42 относится ко 2-й зоне. Разрезы 40-40 и 16-16 показывают отопление."
        },
        {
          "block_id": "blk_5d085f4c917a4e568fd33327e6f8edea",
          "description": "Разрезы 7-7 и 10-10: общие участки циркуляции ГВС 1-й зоны и К15; отдельная ветвь жилья здесь не выделена маркой Т411."
        },
        {
          "block_id": "blk_94b58ecf5d404f7d90c272d267eb2e48",
          "description": "Аксонометрия: узлы ГВС 1-й зоны используются как общий контекст; индивидуальное прослеживание Т411 по мелким подписям не выполнено."
        },
        {
          "block_id": "blk_06029d59a01b4b779037ffcee1ae5260",
          "description": "План с трассами К1 и расположением оборудования не устанавливает отдельный маршрут Т411."
        },
        {
          "block_id": "blk_8e4e78d833774d1094ea7fc72932c0ff",
          "description": "Узел отопления Т11: поперечные обозначения Т4, Т31 и Т42 не позволяют отождествить конкретное сечение с Т411."
        }
      ]
    },
    {
      "object_id": "pipe66_t411",
      "operation": "quantity_balance",
      "status": "needs_data",
      "reason": "Спецификация труб представлена, но количества в ней относятся к типоразмерам трубопровода ИТП в целом. Отдельная длина Т411, её границы учёта и распределение общей длины по ветвям не представлены. На схеме подтверждена отдельная ветвь Т411, однако число её изображений не является количеством материала. Размерные цепочки разреза не задают полную длину трассы. Для баланса нужны ведомость участков Т411 и привязка к конкретной строке спецификации; дефицит или пропуск трубы не установлен.",
      "source_refs": [
        "blk_7527066e645e47bb917a9fc17fb82ccc",
        "blk_0103a941fa5a4b0d9141a4149e927bff",
        "blk_b55acef48d8d452d92a5e3a8fcc2fd88"
      ],
      "quantity_derivation": [],
      "context_queries": [
        "Т411",
        "План трубопроводов ИТП",
        "ведомость трубопроводов",
        "45х2,5",
        "45×2,5"
      ]
    },
    {
      "object_id": "pipe66_t411",
      "operation": "dimension_consistency",
      "status": "checked",
      "reason": "Для обозначенного присоединения Т411 размер Ø45×2,5оц совпадает на разрезе 6-6 и принципиальной схеме. На схеме отдельно показаны местные переходы и общий участок Т41 после объединения с Т412; их размеры нельзя автоматически сравнивать с размером отдельной ветви жилья. В ПЗ Ø57×3,0 относится к расчётному циркуляционному трубопроводу 1-й зоны в целом: последовательность раздела устанавливается по блокам листов 6 и 7. Это не независимое указание размера Т411. В проверенном сопоставлении двух графических обозначений Т411 размерный конфликт не обнаружен. Соответствие позиции спецификации остаётся предметом document_links.",
      "source_refs": [
        "blk_7527066e645e47bb917a9fc17fb82ccc",
        "blk_0103a941fa5a4b0d9141a4149e927bff",
        "blk_ddd03131f0fb4dfc8aeeb087ac60a8a0",
        "blk_fa4cca816905454ab134c787b1d1862a"
      ]
    },
    {
      "object_id": "pipe66_t411",
      "operation": "document_links",
      "status": "needs_data",
      "reason": "Связь Т411 между разрезом 6-6 и принципиальной схемой установлена. Схема связывает Т411 и Т412 с общим Т41 и насосами К15; назначение и рабочая точка К15 согласуются с расчётом насосов, экспликацией и спецификацией оборудования. Однако расчёт распределения циркуляционного расхода между жильём и арендой/ДОО и адресная привязка Т411 к строке спецификации труб отсутствуют в предоставленном пакете. Спецификация содержит общие количества по типоразмерам ГОСТ 3262-75 и ГОСТ 10704-91; выбирать строку по приблизительно похожему диаметру нельзя. Требуется источник соответствия марки ветви, расчётного участка и позиции материала. Отсутствие этих документов во всём проекте не установлено.",
      "source_refs": [
        "blk_7527066e645e47bb917a9fc17fb82ccc",
        "blk_0103a941fa5a4b0d9141a4149e927bff",
        "blk_fed30df45d124919a8b7cc13253733b1",
        "blk_1601889b50624245a5c590ad23d87175",
        "blk_ae35014464b5493f84ca38481c3ffa60",
        "blk_b55acef48d8d452d92a5e3a8fcc2fd88"
      ],
      "context_queries": [
        "Т411",
        "Т412",
        "расчет циркуляции",
        "ведомость трубопроводов",
        "45х2,5",
        "ГОСТ 3262-75"
      ]
    },
    {
      "object_id": "pipe66_t411",
      "operation": "calculation_consistency",
      "status": "needs_data",
      "reason": "Подтверждено локальное документальное расхождение: на разрезе 6-6 для Т411 указан расход 5,89 м³/ч, на принципиальной схеме для той же ветви — 2,78 м³/ч при совпадающих назначении, размере, температуре и давлении. Разные режимы для этих подписей не обозначены. На принципиальной схеме Т411 и Т412 объединяются в Т41, но расчёт режимов и распределения расходов между этими ветвями не представлен. Арифметика расчёта циркуляции 1-й зоны проверена; применимость его итогового расхода к конкретному режиму Т411 остаётся неустановленной. Рабочая точка К15 4,31 м³/ч не является доказательством максимальной подачи. Резервный насос не суммируется с рабочим. Требуются расчёт ветвей и согласованный режим; недостаточность насоса или трубопровода не доказана.",
      "source_refs": [
        "blk_7527066e645e47bb917a9fc17fb82ccc",
        "blk_0103a941fa5a4b0d9141a4149e927bff",
        "blk_fed30df45d124919a8b7cc13253733b1",
        "blk_fa4cca816905454ab134c787b1d1862a",
        "blk_ae35014464b5493f84ca38481c3ffa60"
      ],
      "calculation_checks": [
        {
          "expression": "5,89 - 2,78",
          "result": "3,11",
          "unit": "м³/ч",
          "basis": "Разность подписанных расходов одной ветви Т411 на разрезе 6-6 и принципиальной схеме. Совпадают назначение, размер, T=55 °C и P=8,06 бар; отдельные режимы не указаны. Это документальное расхождение, а не расчёт недостаточности.",
          "source_refs": [
            "blk_7527066e645e47bb917a9fc17fb82ccc",
            "blk_0103a941fa5a4b0d9141a4149e927bff"
          ]
        },
        {
          "expression": "2,78 + 1,57",
          "result": "4,35",
          "unit": "м³/ч",
          "basis": "Условная сумма расходов Т411 и Т412, соединённых на принципиальной схеме в Т41. Для физического баланса необходимо подтвердить одновременность указанных расходов и их расчётный режим; сумма не объявляется утверждённой рабочей точкой К15.",
          "source_refs": [
            "blk_0103a941fa5a4b0d9141a4149e927bff"
          ]
        },
        {
          "expression": "(0,2 × 0,202) / (1 + 0,2)",
          "result": "0,0336666667; в ПЗ принято 0,033",
          "unit": "Гкал/ч",
          "basis": "Формула теплопотерь циркуляции в подразделе ПЗ «1-зона ГВС». Проверена арифметика исходной подстановки; распределение результата между Т411 и Т412 не задано.",
          "source_refs": [
            "blk_fed30df45d124919a8b7cc13253733b1"
          ]
        },
        {
          "expression": "(1,3 × 0,033 × 1000) / 10",
          "result": "4,29",
          "unit": "м/ч — буквальная запись единицы в MD",
          "basis": "Фактическая подстановка принятого в ПЗ Qцирк=0,033 и Δt=10 °C. Арифметика верна. Запись единицы не исправлена автоматически; физическая размерность и связь с объёмным расходом отдельной ветви требуют уточнения.",
          "source_refs": [
            "blk_fed30df45d124919a8b7cc13253733b1"
          ]
        },
        {
          "expression": "(1,3 × ((0,2 × 0,202) / (1 + 0,2)) × 1000) / 10",
          "result": "4,3766666667",
          "unit": "м/ч — по записи расчётной цепочки MD",
          "basis": "Условная проверка без промежуточного округления теплопотерь. Результат не является назначенным расходом Т411; правило округления и физическая применимость к ветви не установлены.",
          "source_refs": [
            "blk_fed30df45d124919a8b7cc13253733b1"
          ]
        },
        {
          "expression": "7,24 + 3 + 5",
          "result": "15,24",
          "unit": "м",
          "basis": "Сумма системных потерь, потерь теплообменника и запаса в расчёте напора насосов ГВС 1-й зоны. Выделение потерь маршрута Т411 в источнике отсутствует.",
          "source_refs": [
            "blk_fed30df45d124919a8b7cc13253733b1"
          ]
        }
      ],
      "context_queries": [
        "Т411",
        "Т412",
        "5,89",
        "2,78",
        "расчет циркуляции",
        "режим циркуляции"
      ]
    }
  ],
  "findings": [
    {
      "object_id": "pipe66_t411",
      "operation": "calculation_consistency",
      "severity": "medium",
      "problem": "Разные значения расхода одной ветви Т411 на разрезе и принципиальной схеме",
      "description": "На разрезе 6-6 для циркуляционной ветви ГВС жилья 1-й зоны Т411 указан G=5,89 м³/ч. На принципиальной схеме у Т411 указан G=2,78 м³/ч. Идентичность ветви подтверждают марка, назначение, Ø45×2,5оц, T=55 °C и P=8,06 бар; соседняя Т412 обозначена отдельно. Разность составляет 3,11 м³/ч. Разделение этих значений по режимам в сравниваемых подписях отсутствует, поэтому расход ветви задан несогласованно. Правильное значение и влияние расхождения на гидравлику по предоставленным источникам не определены; недостаточность К15 или диаметра трубы не установлена.",
      "solution": "По расчёту циркуляции жилья 1-й зоны определить расход Т411 и привести подписи схемы и разреза к согласованному значению. Если значения относятся к разным режимам, явно обозначить режимы и дать ссылку на расчёт распределения расходов Т411 и Т412.",
      "sheet": "ИТП.ТМ: лист 6, разрез 6-6; лист 2, принципиальная схема",
      "evidence": [
        {
          "block_id": "blk_7527066e645e47bb917a9fc17fb82ccc",
          "description": "Верхняя левая подпись разреза 6-6, проверенная по увеличенному изображению: Т411, циркуляция ГВС жилья 1-й зоны, Ø45×2,5оц, G=5,89 м³/ч, T=55 °C, P=8,06 бар."
        },
        {
          "block_id": "blk_0103a941fa5a4b0d9141a4149e927bff",
          "description": "Верхняя левая группа ветвей ГВС на увеличении принципиальной схемы: Т411 жилья с Ø45×2,5оц, G=2,78 м³/ч, T=55 °C, P=8,06 бар. Т412 аренды/ДОО показана отдельной ветвью; ниже обе соединяются в Т41."
        }
      ],
      "report_section": "technical_findings"
    }
  ]
}
